package httpapi

import "net/http"

const dashboardHTML = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>宠物门店预约</title>
<style>
:root{color-scheme:light;--ink:#17202a;--muted:#68737d;--line:#d9dee3;--accent:#176b87;--danger:#a13d3d;--surface:#fff;--bg:#f5f7f8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif;letter-spacing:0}main{max-width:1180px;margin:0 auto;padding:24px 18px 56px}header{display:flex;justify-content:space-between;gap:16px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:16px;margin-bottom:18px}h1{font-size:24px;margin:0}h2{font-size:17px;margin:0 0 12px}h3{font-size:15px;margin:14px 0 8px}section{background:var(--surface);border:1px solid var(--line);padding:17px;margin-bottom:14px}label{display:grid;gap:5px;color:var(--muted);font-size:13px}input,select,button,textarea{font:inherit;padding:9px 10px;border:1px solid #bac4cc;border-radius:4px;min-width:0}textarea{min-height:70px;resize:vertical}button{background:var(--accent);border-color:var(--accent);color:#fff;cursor:pointer}button.secondary{background:#fff;color:var(--accent)}button.danger{background:#fff;color:var(--danger);border-color:var(--danger)}form.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:10px;align-items:end}.actions{display:flex;flex-wrap:wrap;gap:8px}.hidden{display:none!important}.notice{padding:10px 12px;background:#eef5f7;border-left:3px solid var(--accent);margin-bottom:14px;white-space:pre-wrap}.error{color:var(--danger);border-left-color:var(--danger);background:#fff3f3}.meta{color:var(--muted);font-size:13px}.workspace{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.workspace section{margin:0}.wide{grid-column:1/-1}.result{overflow:auto;max-height:520px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;border-bottom:1px solid var(--line);padding:8px 7px;vertical-align:top;white-space:nowrap}th{color:var(--muted);font-weight:600;background:#fafbfb}.empty{padding:20px 4px;color:var(--muted)}@media(max-width:760px){header{align-items:flex-start;flex-direction:column}.workspace{grid-template-columns:1fr}.wide{grid-column:auto}}
</style></head><body><main>
<header><div><h1>宠物门店预约</h1><div id="identity" class="meta">未登录</div></div><button id="logout" class="danger hidden" type="button">退出</button></header><div id="notice" class="notice">请使用预置账号登录。</div>
<section id="loginPanel"><h2>登录</h2><form id="loginForm" class="grid"><label>账号<input name="username" autocomplete="username" required></label><label>密码<input name="password" type="password" autocomplete="current-password" required></label><button>登录</button></form></section>
<div id="app" class="hidden workspace">
<section class="wide"><h2>业务查询</h2><form id="queryForm" class="grid"><label>业务日期<input id="date" type="date" required></label><div class="actions"><button type="button" id="slots">查询时段</button><button type="button" id="bookings">查询预约</button><button type="button" id="daily" data-roles="manager">查询日清</button></div></form></section>
<section data-roles="manager"><h2>店长</h2><h3>发布时段</h3><form id="slotForm" class="grid"><label>项目编号<input name="project_id" type="number" min="1" value="1" required></label><label>开始时间<input name="start_at" type="datetime-local" required></label><label>结束时间<input name="end_at" type="datetime-local" required></label><label>容量<input name="capacity" type="number" min="1" max="3" value="3" required></label><button>发布</button></form><h3>教学时钟</h3><form id="clockForm" class="grid"><label>推进分钟<input name="minutes" type="number" min="1" value="5" required></label><button>推进</button></form></section>
<section data-roles="owner"><h2>宠物主人</h2><h3>预约</h3><form id="bookingForm" class="grid"><label>宠物编号<input name="pet_id" type="number" min="1" required></label><label>时段编号<input name="slot_id" type="number" min="1" required></label><button>提交预约</button></form><h3>发起支付</h3><form id="paymentForm" class="grid"><label>预约编号<input name="booking_id" type="number" min="1" required></label><button>创建支付</button></form><h3>取消</h3><form id="cancelForm" class="grid"><label>预约编号<input name="booking_id" type="number" min="1" required></label><label>取消原因<input name="reason"></label><div class="actions"><button type="button" data-cancel="unpaid">取消未付款预约</button><button type="button" data-cancel="request">提交取消申请</button></div></form></section>
<section data-roles="support"><h2>客服</h2><h3>审核取消申请</h3><form id="reviewForm" class="grid"><label>申请编号<input name="request_id" type="number" min="1" required></label><label>审核结果<select name="approve"><option value="true">批准</option><option value="false">拒绝</option></select></label><button>提交审核</button></form><h3>退款渠道回调</h3><form id="refundForm" class="grid"><label>原始 JSON<textarea name="payload" required>{"refund_id":1,"outcome":"success"}</textarea></label><label>HMAC 签名<input name="signature" required></label><button>发送退款回调</button></form></section>
<section data-roles="desk,worker,manager"><h2>现场履约</h2><form id="actionForm" class="grid"><label>预约编号<input id="bookingId" type="number" min="1" required></label><label>原因<input id="reason" placeholder="未到店原因"></label><div class="actions"><button type="button" data-action="check-in" data-roles="desk">核销</button><button type="button" data-action="service/start" data-roles="worker">开始服务</button><button type="button" data-action="service/complete" data-roles="worker">完成服务</button><button type="button" data-action="no-show" data-roles="manager">标记未到店</button><button type="button" data-action="expire" data-roles="manager">关闭超时预约</button></div></form></section>
<section data-roles="support,manager"><h2>模拟支付渠道</h2><form id="channelForm" class="grid"><label>原始 JSON<textarea name="payload" required>{"payment_id":1,"booking_id":1,"amount_cents":9900,"outcome":"success"}</textarea></label><label>HMAC 签名<input name="signature" required></label><button>发送支付回调</button></form></section>
<section class="wide"><h2>结果</h2><div id="result" class="result"><div class="empty">尚未操作</div></div></section></div></main>
<script>
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const notice=(text,bad=false)=>{$('#notice').textContent=text;$('#notice').className=bad?'notice error':'notice'};const json=async r=>{const t=await r.text();let x;try{x=JSON.parse(t)}catch{x=t}if(!r.ok)throw new Error(typeof x==='string'?x:(x.error||t||'HTTP '+r.status));return x};const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderTable(value){const target=$('#result');if(value===null||value===undefined){target.innerHTML='<div class="empty">无结果</div>';return}const rows=Array.isArray(value)?value:(value.bookings||value.slots);if(Array.isArray(rows)){if(!rows.length){target.innerHTML='<div class="empty">暂无记录</div>';return}const keys=[...new Set(rows.flatMap(Object.keys))];target.innerHTML='<table><thead><tr>'+keys.map(k=>'<th>'+escapeHTML(k)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+keys.map(k=>'<td>'+escapeHTML(typeof row[k]==='object'?JSON.stringify(row[k]):row[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table>';return}target.innerHTML='<table><tbody>'+Object.entries(value).map(([k,v])=>'<tr><th>'+escapeHTML(k)+'</th><td>'+escapeHTML(typeof v==='object'?JSON.stringify(v):v)+'</td></tr>').join('')+'</tbody></table>'}
async function call(path,options){try{const x=await json(await fetch(path,options));renderTable(x);notice('操作成功');return x}catch(err){notice(err.message,true);throw err}}function formBody(form){return new URLSearchParams(new FormData(form))}function applyRole(role){$$('[data-roles]').forEach(el=>{const roles=el.dataset.roles.split(',');el.classList.toggle('hidden',!roles.includes(role))})}async function refresh(){const me=await json(await fetch('/me'));$('#identity').textContent=me.Role+' · 账号 '+me.ID;$('#loginPanel').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');applyRole(me.Role)}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();try{await json(await fetch('/login',{method:'POST',body:formBody(e.target)}));await refresh();notice('登录成功')}catch(err){notice(err.message,true)}});$('#logout').addEventListener('click',async()=>{await fetch('/logout',{method:'POST'});location.reload()});$('#slots').addEventListener('click',()=>call('/slots?date='+encodeURIComponent($('#date').value)));$('#bookings').addEventListener('click',()=>call('/bookings?date='+encodeURIComponent($('#date').value)));$('#daily').addEventListener('click',()=>call('/daily-summary?date='+encodeURIComponent($('#date').value)));$('#slotForm').addEventListener('submit',e=>{e.preventDefault();call('/slots',{method:'POST',body:formBody(e.target)})});$('#clockForm').addEventListener('submit',async e=>{e.preventDefault();const r=await fetch('/clock/advance',{method:'POST',body:formBody(e.target)});if(!r.ok)await json(r);notice('教学时钟已推进')});$('#bookingForm').addEventListener('submit',e=>{e.preventDefault();call('/bookings',{method:'POST',body:formBody(e.target)})});$('#paymentForm').addEventListener('submit',e=>{e.preventDefault();call('/payments',{method:'POST',body:formBody(e.target)})});
$$('[data-cancel]').forEach(button=>button.addEventListener('click',()=>{const f=$('#cancelForm'),id=f.elements.booking_id.value,request=button.dataset.cancel==='request',body=new URLSearchParams();if(request)body.set('reason',f.elements.reason.value);call('/bookings/'+id+(request?'/cancel-request':'/cancel'),{method:'POST',body})}));$('#reviewForm').addEventListener('submit',e=>{e.preventDefault();const f=e.target,id=f.elements.request_id.value,body=new URLSearchParams({approve:f.elements.approve.value});call('/cancellation-requests/'+id+'/review',{method:'POST',body})});$('#refundForm').addEventListener('submit',e=>{e.preventDefault();const f=e.target;call('/refunds/callback',{method:'POST',headers:{'Content-Type':'application/json','X-Signature':f.elements.signature.value},body:f.elements.payload.value})});$('#channelForm').addEventListener('submit',e=>{e.preventDefault();const f=e.target;call('/payments/callback',{method:'POST',headers:{'Content-Type':'application/json','X-Signature':f.elements.signature.value},body:f.elements.payload.value})});
$$('[data-action]').forEach(button=>button.addEventListener('click',()=>{const id=$('#bookingId').value;if(!id){notice('请输入预约编号',true);return}const action=button.dataset.action,body=new URLSearchParams();if(action==='no-show')body.set('reason',$('#reason').value);call('/bookings/'+id+'/'+action,{method:'POST',body})}));const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());$('#date').value=today;
</script></body></html>`

func serveDashboard(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = w.Write([]byte(dashboardHTML))
}
